function ColorPalette({value,onChange,label}:{value:string;onChange:(value:string)=>void;label:string}){
 const [open,setOpen]=useState(false);
 const [custom,setCustom]=useState(false);
 return <div style={{position:'relative',display:'inline-flex',alignItems:'center',gap:8}}>
  <button type="button" aria-label={label} title={label} onClick={()=>setOpen(v=>!v)} style={{width:36,height:30,padding:3,border:'1px solid var(--border,#737373)',borderRadius:5,background:'transparent',cursor:'pointer',display:'grid',placeItems:'center'}}>
   <span style={{display:'block',width:24,height:22,borderRadius:3,background:value,border:'1px solid #888'}}/>
  </button><span style={{fontSize:12,fontFamily:'monospace',color:'var(--muted,#888)'}}>{String(value).toUpperCase()}</span>
  {open&&<div style={{position:'absolute',zIndex:1200,top:36,left:0,width:248,padding:10,borderRadius:8,background:'var(--panel,#fff)',color:'var(--text,#222)',border:'1px solid var(--border,#ccc)',boxShadow:'0 6px 24px #0003'}}>
   <div style={{display:'grid',gridTemplateColumns:'repeat(10,1fr)',gap:4}}>
    {TV_RAY_COLORS.flat().map((color:string,i:number)=><button type="button" key={color+'-'+i} aria-label={color} title={color} onClick={()=>{onChange(color);setCustom(false);setOpen(false)}} style={{width:17,height:17,padding:0,border:color.toLowerCase()===value.toLowerCase()?'2px solid var(--text,#222)':'1px solid #0001',outline:color.toLowerCase()===value.toLowerCase()?'1px solid var(--panel,#fff)':'none',borderRadius:3,background:color,cursor:'pointer'}}/>)}
   </div>
   <div style={{borderTop:'1px solid var(--border,#ddd)',marginTop:10,paddingTop:9,display:'flex',alignItems:'center',gap:8}}>
    <button type="button" onClick={()=>setCustom(v=>!v)} title="Custom color" style={{width:28,height:28,border:'1px solid var(--border,#aaa)',borderRadius:4,background:'transparent',color:'inherit',fontSize:20,cursor:'pointer'}}>+</button>
    {custom&&<input aria-label="Custom color" type="color" value={value} onChange={e=>onChange(e.target.value)} style={{width:32,height:28,padding:0,border:0,background:'transparent'}}/>}
   </div>
  </div>}
 </div>
}
